package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch119 {
    val stories = listOf(
        StorySeries(
            id = "the_library_clock_repair_team",
            title = "The Library Clock Repair Team",
            tagline = "A stopped clock inspires students to document its history and support a careful restoration.",
            parts = listOf(
                StoryPart(1, "Five Minutes Past", listOf("The clock above the library entrance had stopped at five minutes past four. Students had walked beneath it for years, assuming someone would eventually repair it.", "Ada asked the librarian whether the clock had any special history. The librarian found an old photograph showing it at the opening of the building.", "The school invited a qualified clock repairer to inspect it and asked the students to help gather its story.")),
                StoryPart(2, "The Photograph Album", listOf("The students searched the library archive for photographs of the entrance. They found images from several decades, each showing the clock in a different condition.", "They recorded the dates and source of each photograph, leaving uncertain dates marked as approximate.", "Ada noticed that the clock face had been repainted at least once, and the repairer confirmed that this detail would be useful background.")),
                StoryPart(3, "The Repairer's Visit", listOf("The repairer examined the clock and explained that the students should not open or adjust it. The mechanism required specialist attention and proper equipment.", "Ada wrote down the repairer's public explanation in simple language, then read it back to make sure she had understood.", "The group agreed to keep the clock in place until the professional work could be scheduled.")),
                StoryPart(4, "A Collection of Memories", listOf("The librarian invited former students to share memories of the clock. One remembered using it to judge whether they had time to borrow a book before class.", "Another recalled that the clock had been covered during a renovation. The students checked the building records before adding that detail to the timeline.", "They included only memories whose contributors agreed to have them displayed.")),
                StoryPart(5, "A Confusing Date", listOf("Two photographs seemed to show the clock before and after a renovation, but their handwritten dates disagreed.", "The archive volunteer found a school newsletter that helped establish the correct sequence. The students changed the timeline and added a source note.", "Ada learned that a neat story was less important than an accurate one.")),
                StoryPart(6, "The Restoration Plan", listOf("The repairer provided a schedule for the restoration and explained which parts could be preserved. The library arranged the work for a time when the entrance could be safely managed.", "The students prepared a small display about the clock's history and added a note that the repair was being completed by a professional.", "They planned a reveal for the day the restored clock could be checked and returned to service.")),
                StoryPart(7, "Waiting Together", listOf("While the repair took place, the students placed a temporary sign near the entrance explaining that the clock was being restored.", "Some visitors asked when it would work again. The librarian gave the approved schedule and reminded everyone not to enter the work area.", "Ada realised that a restoration was not only about the final result; it also involved making the process understandable.")),
                StoryPart(8, "The First Tick", listOf("The repairer completed the work and tested the clock according to the restoration plan. The hands moved again, and the clock was checked against a reliable time reference.", "The students watched from the visitor area as the librarian thanked the repairer. The old clock face looked familiar, but its movement was steady.", "Ada added the restoration date to the archive timeline.")),
                StoryPart(9, "The Display Opens", listOf("The library unveiled the photograph display beside the entrance. Visitors could see the clock across the years and read the approved memories beside each image.", "A former student recognised a photograph from a school celebration and offered to identify the event. The archive volunteer recorded the suggestion for later checking.", "The display invited people to contribute, but every new detail would be reviewed before publication.")),
                StoryPart(10, "Time Well Kept", listOf("The clock continued to work, and the library added a yearly inspection reminder to its maintenance calendar.", "Ada placed the original photograph back in its protective sleeve and saved the updated timeline with the archive records.", "The clock no longer showed five minutes past four. It showed the present, while its photographs and memories kept the past close enough for the next generation to discover."))
            )
        )
    )
